    side={{1029741,"Impaan the Imprisoner",{0.4922,0.4261,0.4634,0.5526,0.4307,0.7116}},{1029741,"Moontouched Wanderer",{0.6387,0.5769,0.668,0.675}}},
    stops={{"boss",1029742,0.2344,0.4773,"마른아귀","Withermaw","첫 번째 우두머리, 썩어가는 소굴 서쪽 끝 연못 옆; 동굴 입구는 호수 동쪽에 있고, 소굴은 막다른 곳입니다","First boss, at the west end of the Festering Grotto by the pond; the cave mouth is east of the lake, the grotto is a dead end",{3315}},{"optional",1029741,0.4307,0.7116,"간수 임판","Impaan the Imprisoner","선택: 위치는 애드온 하나 기준, 영상 런에는 없음; 더럽혀진 봉우리의 가시 고리 한가운데","Optional: place from one addon only, not in the video run; in the middle of the thorn ring at Defiled Peak",{3316}},{"boss",1029741,0.6387,0.5769,"꺾이지 않는 해골주둥이","Bonesnout the Unbroken","통나무 길 옆 해골주둥이의 숲을 순찰; Legashi Ritualist 4명이 죽을 때까지 보호막에 싸여 있습니다","Patrols Bonesnout's Thicket by the log walkway; shielded until the four Legashi Ritualists are dead",{3322}},{"rare",1029741,0.668,0.675,"Moontouched Wanderer","Moontouched Wanderer","희귀, 매번 나오지 않음: 꺾이지 않는 해골주둥이 남쪽","Rare, not in every run: south of Bonesnout",{}},{"boss",1029745,0.5645,0.3514,"검은아귀 거수","Blackmaw Behemoth","지하의 큰 붉은 홀 (굴의 나락); 해골주둥이의 숲 동쪽 문을 통과해 퀘스트 제공자를 지나 아래로","Underground in the big red hall (Depths of the Burrow); through the gate east of Bonesnout's Thicket, down past the quest giver",{3323}},{"boss",1029746,0.582,0.5681,"바록스 블릭후프","Varrox Bleakhoof","맨 아래 보라색 마법진 (금지된 마법의 나락); 검은아귀 거수의 홀 옆 둥근 구멍을 지나세요","At the very bottom in the purple magic circle (Depths of Forbidden Magic); through the round hole next to the Behemoth's hall",{3334}},{"rare",1029746,0.5967,0.6501,"Gortek the Apprentice","Gortek the Apprentice","희귀, 매번 나오지 않음: 바록스 블릭후프의 마법진 옆 해골 근처","Rare, not in every run: by the skull next to Varrox's circle",{}},{"boss",1029744,0.4307,0.3529,"장로 주술사 핏빛갈기","Elder Shaman Bloodmane","초록빛으로 빛나는 방 (장로의 나락); 다시 올라가 검은아귀 거수의 홀을 지나 북쪽으로; 주변의 Devotee를 먼저 처치하고, 그의 연쇄 번개를 차단하세요","In the green glowing room (Depths of the Elders); back up past the Behemoth's hall and north; kill the Devotees around him first, interrupt his Chain Lightning",{3327}},{"boss",1029743,0.5547,0.3031,"속박 풀린 영혼","Unbound Spirit","마지막 우두머리, 큰 나무 오두막 (몰락한 숲의 나락); 우호적인 펄볼그 Elder Bramblesnap에게 말을 걸면 전투가 시작됩니다","Last boss, at the big wooden hut (Depths of the Fallen Grove); talk to the friendly furbolg Elder Bramblesnap to start the fight",{3336}}},
    notes={{1029741,0.207,0.6149,"영상 런 하나와 애드온 하나로 만든 대략적인 경로; 지하에서는 지도가 층을 자동으로 바꾸지 않으니 층 탭을 사용하세요","Rough route from one video run and one addon; underground the map does not switch levels by itself, use the level tabs"}},
